 const [view,setView]=useState("auth"),[dashboardTab,setDashboardTab]=useState("dashboard"),[authMode,setAuthMode]=useState("choice"),[phone,setPhone]=useState(""),[password,setPassword]=useState(""),[email,setEmail]=useState(""),[name,setName]=useState(""),[examTarget,setExamTarget]=useState("Banking"),[state,setState]=useState(""),[authBusy,setAuthBusy]=useState(false),[authError,setAuthError]=useState(""),[test,setTest]=useState(1),[section,setSection]=useState("essay"),[agree,setAgree]=useState(false),[time,setTime]=useState(1800),[essay,setEssay]=useState(""),[selectedEssay,setSelectedEssay]=useState(""),[comp,setComp]=useState(["","","","",""]),[evaluation,setEvaluation]=useState(null),[busy,setBusy]=useState(false),[error,setError]=useState(""),[attempts,setAttempts]=useState({}),[photo,setPhoto]=useState(""),[reviews,setReviews]=useState([]),[myReview,setMyReview]=useState(null),[reviewRating,setReviewRating]=useState(0),[reviewText,setReviewText]=useState(""),[reviewBusy,setReviewBusy]=useState(false),[reviewAverage,setReviewAverage]=useState(null),[reviewCount,setReviewCount]=useState(0),[reviewOpen,setReviewOpen]=useState(false),[countdown,setCountdown]=useState({days:0,hours:0,minutes:0,seconds:0});
 useEffect(()=>{(async()=>{try{const r=await fetch("/api/auth");const d=await r.json();if(r.ok&&d.authenticated&&d.user){const u=d.user;setName(u.name||"Student");setPhone(u.phone||"");setEmail(u.email||"");setExamTarget(u.exam_target||"Banking");setState(u.state||"");setPhoto(localStorage.getItem("dm_profile_photo")||localStorage.getItem("dm_profile_photo_v2")||"");localStorage.setItem("dm_logged","1");localStorage.setItem("dm_name",u.name||"Student");localStorage.setItem("dm_phone",u.phone||"");try{const ar=await fetch("/api/attempts?phone="+encodeURIComponent(u.phone));const ad=await ar.json();if(ar.ok){const restored={};(ad.attempts||[]).forEach(a=>{const n=Number(a.test_no);if(n&&!restored[n])restored[n]={selectedEssay:a.essay_topic||"",essay:a.essay||"",comp:Array.isArray(a.comp_answers)?a.comp_answers:["","","","",""],evaluation:a.evaluation||null,submittedAt:a.submitted_at};});setAttempts(restored);localStorage.setItem("dm_attempts",JSON.stringify(restored));}}catch(e){}setView("dashboard")}}catch(e){}})()},[]);
