 async function handleProfilePhoto(e){
  const file=e.target.files?.[0];
  if(!file||!file.type.startsWith("image/"))return;
  if(file.size>5*1024*1024){alert("Please choose an image smaller than 5 MB.");return;}
  const reader=new FileReader();
  reader.onload=ev=>{
    const img=new Image();
    img.onload=()=>{
      const size=320,canvas=document.createElement("canvas");
      canvas.width=size;canvas.height=size;
      const ctx=canvas.getContext("2d");
      const scale=Math.max(size/img.width,size/img.height);
      const w=img.width*scale,h=img.height*scale;
      ctx.drawImage(img,(size-w)/2,(size-h)/2,w,h);
      const data=canvas.toDataURL("image/jpeg",0.82);
      setPhoto(data);
      try{localStorage.setItem("dm_profile_photo",data);}catch(e){alert("Photo could not be saved. Please try a smaller image.");}
    };
    img.src=String(ev.target?.result||"");
  };
  reader.readAsDataURL(file);
}

 async function submitReview(){if(!reviewRating)return alert("Please select a star rating.");if(reviewText.trim().length<3)return alert("Please write a short review.");setReviewBusy(true);try{const r=await fetch("/api/reviews",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({rating:reviewRating,comment:reviewText})});const d=await r.json();if(!r.ok)throw new Error(d.error||"Could not save review");setMyReview(d.review);const rr=await fetch("/api/reviews");const rd=await rr.json();if(rr.ok){setReviews(rd.reviews||[]);setReviewAverage(rd.average||null);setReviewCount(Number(rd.count)||0);} }catch(e){alert(e.message||"Could not save review")}finally{setReviewBusy(false)}}

 useEffect(()=>{if(view==="exam"&&time===0)submit()},[time,view]); useEffect(()=>{function tick(){const target=new Date("2026-10-04T00:00:00+05:30").getTime(),diff=Math.max(0,target-Date.now()),total=Math.floor(diff/1000);setCountdown({days:Math.floor(total/86400),hours:Math.floor((total%86400)/3600),minutes:Math.floor((total%3600)/60),seconds:total%60});}tick();const id=setInterval(tick,1000);return()=>clearInterval(id);},[]);
