    try{const ar=await fetch("/api/attempts?phone="+encodeURIComponent(u.phone));const ad=await ar.json();if(ar.ok){const restored={};(ad.attempts||[]).forEach(a=>{const n=Number(a.test_no);if(n&&!restored[n])restored[n]={selectedEssay:a.essay_topic||"",essay:a.essay||"",comp:Array.isArray(a.comp_answers)?a.comp_answers:["","","","",""],evaluation:a.evaluation||null,submittedAt:a.submitted_at};});setAttempts(restored);localStorage.setItem("dm_attempts",JSON.stringify(restored));}}catch(e){}
